begin;
set local lock_timeout='5s';
set local statement_timeout='300s';
set local timezone='UTC';
drop table if exists public._release_protected_before;
create table public._release_protected_before(career_id uuid,table_name text,predicate text,cols text[],n bigint,hash text,primary key(career_id,table_name));
alter table public._release_protected_before enable row level security;
revoke all on public._release_protected_before from public,anon,authenticated;
do $$ declare c record;t record;pred text;h text;n bigint;begin
 perform 1 from public.careers order by id for update;
 for c in select id from public.careers order by id loop
  for t in select tab.table_name::text table_name,array_agg(col.column_name::text order by col.column_name) cols
   from information_schema.tables tab join information_schema.columns col using(table_schema,table_name)
   where tab.table_schema='public' and tab.table_type='BASE TABLE' and tab.table_name not in('_release_protected_before')
   group by tab.table_name order by tab.table_name loop
   pred:=case when t.table_name='careers' then 'id=$1' when 'career_id'=any(t.cols) then 'career_id=$1'
    when 'season_id'=any(t.cols) then 'season_id in(select id from public.career_seasons where career_id=$1)'
    when 'fixture_id'=any(t.cols) then 'fixture_id in(select f.id from public.season_fixtures f join public.career_seasons s on s.id=f.season_id where s.career_id=$1)' end;
   if pred is null then continue;end if;
   execute format('select count(*),md5(coalesce(string_agg(h,'''' order by h),'''')) from(select md5((select jsonb_object_agg(k,v) from jsonb_each(to_jsonb(x)) e(k,v) where k=any($2))::text) h from public.%I x where %s)z',t.table_name,pred) into n,h using c.id,t.cols;
   insert into public._release_protected_before values(c.id,t.table_name,pred,t.cols,n,h);
  end loop;
 end loop;
end $$;
-- Evolução 67 — Transferências no formato do CM17: pré-seleção de atletas observados.
-- A aba "Mundo" vira Transferências (busca, pré-seleção, olheiros, negociações e lista de venda); notícias chegam
-- pela Caixa de entrada e as finanças ficam no Clube (só frontend). Aqui entra apenas a lista de pré-seleção.

create table if not exists public.cw_shortlist(
 career_id uuid not null references public.careers(id) on delete cascade,
 player_id text not null references public.sim_players(id),
 added_on timestamptz not null default now(),
 primary key(career_id,player_id));
alter table public.cw_shortlist enable row level security;
revoke all on public.cw_shortlist from public,anon,authenticated;

create or replace function public.career_shortlist_toggle(p_player text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare car public.careers;on_list boolean;
begin
 car:=public.mgr_lock();
 if not exists(select 1 from public.sim_players where id=p_player and active) then raise exception 'Atleta não encontrado';end if;
 delete from public.cw_shortlist where career_id=car.id and player_id=p_player;
 if not found then
  if (select count(*) from public.cw_shortlist where career_id=car.id)>=50 then raise exception 'A pré-seleção aceita até 50 atletas.';end if;
  insert into public.cw_shortlist(career_id,player_id) values(car.id,p_player);on_list:=true;
 else on_list:=false;end if;
 return jsonb_build_object('ok',true,'shortlisted',on_list);
end $$;

create or replace function public.career_shortlist()
returns jsonb language plpgsql stable security definer set search_path=public as $$
declare car uuid:=public.cw_current_career();w public.cw_world;
begin
 if car is null then raise exception 'Carreira ativa não encontrada';end if;
 select * into w from public.cw_world where career_id=car;
 return(select coalesce(jsonb_agg(to_jsonb(x) order by x.overall desc,x.id),'[]') from(
  select sp.id,sp.full_name name,sp.short_name,sp.position,e.club_id,sp.nationality,round(pr.rating) overall,
   coalesce(cp.age_at_start,sp.age,case when sp.is_youth then 19 else 26 end)+coalesce(floor((w.today-w.started_on)/365.25)::int,0) age,
   public.cw_player_value(car,sp.id) value,ct.monthly_salary,ct.expires_on,true shortlisted
  from public.cw_shortlist s join public.sim_players sp on sp.id=s.player_id
  join public.sim_player_pos_ratings pr on pr.player_id=sp.id and pr.pos=sp.position
  left join public.cw_players cp on cp.career_id=car and cp.player_id=sp.id
  cross join lateral(select public.cw_effective_player_club(car,sp.id) club_id)e
  left join public.cw_contracts ct on ct.career_id=car and ct.player_id=sp.id and ct.status='active'
  where s.career_id=car)x);
end $$;

revoke all on function public.career_shortlist_toggle(text),public.career_shortlist() from public,anon;
grant execute on function public.career_shortlist_toggle(text),public.career_shortlist() to authenticated;
notify pgrst,'reload schema';

do $$ declare r record;h text;n bigint;begin
 if not exists(select 1 from public._release_protected_before) and exists(select 1 from public.careers) then
  raise exception 'Snapshot de preservação ausente; execute o arquivo inteiro de uma vez';
 end if;
 for r in select * from public._release_protected_before order by career_id,table_name loop
  execute format('select count(*),md5(coalesce(string_agg(h,'''' order by h),'''')) from(select md5((select jsonb_object_agg(k,v) from jsonb_each(to_jsonb(x)) e(k,v) where k=any($2))::text) h from public.%I x where %s)z',r.table_name,r.predicate) into n,h using r.career_id,r.cols;
  if n<>r.n or h<>r.hash then raise exception 'Protected progress differs in table %; deployment rolled back',r.table_name;end if;
 end loop;
 raise notice 'Protected progress verified for % careers, % table comparisons',(select count(distinct career_id) from public._release_protected_before),(select count(*) from public._release_protected_before);
end $$;
drop table public._release_protected_before;
notify pgrst,'reload schema';
commit;
